# --- Positive: each route reaches its service method, returns the pinned DTO --------


def test_file_transaction_detail_reaches_service_and_returns_201(admin_client, monkeypatch):
    http, stub_user, _set_role = admin_client
    captured: dict = {}
    allotment_id = uuid.uuid4()

    def _fake_file(self, aid, req, *, filed_by):
        captured["allotment_id"] = aid
        captured["req"] = req
        captured["filed_by"] = filed_by
        return _stub_dto(id=uuid.uuid4(), allotment_id=aid, filed_by=filed_by)

    monkeypatch.setattr(
        OnboardingService, "file_transaction_detail", _fake_file, raising=False
    )

    resp = http.post(
        f"/api/rm/allotments/{allotment_id}/transaction-detail", json=_post_body()
    )
    assert resp.status_code == 201, resp.text
    body = resp.json()
    assert body["allotment_id"] == str(allotment_id)
    assert body["bank_account"] == "123-456-789"
    assert body["currency"] == "USD"
    assert captured["allotment_id"] == allotment_id
    assert captured["filed_by"] == stub_user.firebase_uid
    assert captured["req"].currency == "USD"


def test_get_transaction_detail_reaches_service_and_returns_200(admin_client, monkeypatch):
    http, _stub_user, _set_role = admin_client
    captured: dict = {}
    allotment_id = uuid.uuid4()

    def _fake_get(self, aid):
        captured["allotment_id"] = aid
        return _stub_dto(id=uuid.uuid4(), allotment_id=aid)

    monkeypatch.setattr(OnboardingService, "get_transaction_detail", _fake_get, raising=False)

    resp = http.get(f"/api/rm/allotments/{allotment_id}/transaction-detail")
    assert resp.status_code == 200, resp.text
    assert resp.json()["allotment_id"] == str(allotment_id)
    assert captured["allotment_id"] == allotment_id


# --- Negative: wrong role on each route returns 403, service never reached ----------


@pytest.mark.parametrize("role", [AdminRole.MOBO, AdminRole.PM, AdminRole.PC, AdminRole.COMPLIANCE])
def test_file_transaction_detail_wrong_role_gets_403(admin_client, monkeypatch, role):
    http, _stub_user, set_role = admin_client
    called = {"hit": False}
    monkeypatch.setattr(
        OnboardingService,
        "file_transaction_detail",
        lambda self, aid, req, *, filed_by: called.update(hit=True) or _stub_dto(),
        raising=False,
    )
    set_role(role)
    resp = http.post(
        f"/api/rm/allotments/{uuid.uuid4()}/transaction-detail", json=_post_body()
    )
    assert resp.status_code == 403
    assert called["hit"] is False


