# --- Invariant: no path collision with existing /rm/* paths -------------------------


def test_new_routes_registered_without_colliding_with_existing_paths():
    paths = set(app.openapi()["paths"].keys())
    for expected in (
        "/api/rm/allotments/{allotment_id}/transaction-detail",
    ):
        assert expected in paths, f"missing route {expected}"
    for existing in (
        "/api/rm/allotment",
        "/api/rm/redemption",
        "/api/rm/subscriptions/{client_id}/allotments",
    ):
        assert existing in paths, f"existing route {existing} was shadowed"


